import { dirname } from 'node:path'
import { pathToFileURL } from 'node:url'

/**
 * Where a Craft builder (`craft-native/ios`, `craft-native/android`) is
 * imported from: the copy @stacksjs/mobile resolves, not the one at the
 * project root.
 *
 * The pages call the native bridge through @stacksjs/mobile, so the app has to
 * be generated by the Craft that package was built against. A bare
 * `import('craft-native/ios')` from here resolved whichever copy the package
 * manager had hoisted to the root, and when two framework packages asked for
 * different minimum versions the root kept the older one: the app was built
 * from an old template that lacked bridge actions the pages then called. Apps
 * pinned craft-native with package.json overrides to get past it.
 *
 * Falls back to the bare specifier when @stacksjs/mobile is not installed.
 */
export function craftBuilderSpecifier(builder: 'ios' | 'android', root: string): string {
  try {
    const mobile = Bun.resolveSync('@stacksjs/mobile/package.json', root)
    return pathToFileURL(Bun.resolveSync(`craft-native/${builder}`, dirname(mobile))).href
  }
  catch {
    return `craft-native/${builder}`
  }
}
